const body = $json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('invalid_request');
const allowedFields = new Set(['operation', 'runId']);
if (Object.keys(body).some((key) => !allowedFields.has(key)) || Object.keys(body).length !== 2) throw new Error('unexpected_request_field');
const { operation, runId } = body;
if (!['structure', 'grants', 'probe', 'cleanup'].includes(operation)) throw new Error('invalid_operation');
if (typeof runId !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(runId)) throw new Error('invalid_run_id');
return [{ json: { operation, runId } }];

