const request = $('Normalize Acceptance Request').first().json;
const bases = Array.isArray($json) ? $json : ($json.list || $json.data || []);
const matches = bases.filter((base) => base && base.title === 'issue334_acceptance');
if (matches.length !== 1 || !matches[0].id) throw new Error(matches.length > 1 ? 'duplicate_acceptance_base' : 'acceptance_base_missing');
return [{ json: { ...request, domain: 'issue334_acceptance', baseId: matches[0].id } }];

const context = $('Resolve Acceptance Base').first().json;
const items = $input.all().map((item) => item.json);
const sources = Array.isArray($json) ? $json : ($json.list || $json.data || (items.every((item) => item && item.id) ? items : []));
const reader = sources.filter((source) => source && source.alias === 'Read Model');
const operator = sources.filter((source) => source && source.alias === 'Operator');
if (reader.length !== 1 || operator.length !== 1) throw new Error('acceptance_source_set_invalid');
return [{ json: { ...context, sources, readerSourceId: reader[0].id, operatorSourceId: operator[0].id } }];

const direct = $json.tables !== undefined ? $json : null;
const context = direct || $('Keep Acceptance Sources').first().json;
const items = $input.all().map((item) => item.json);
const raw = direct ? direct.tables : $json;
const tables = Array.isArray(raw) ? raw : (raw.list || raw.data || (items.every((item) => item && item.id) ? items : []));
const expected = [
  { title: 'acceptance_facts', tableName: 'acceptance_facts', sourceId: context.readerSourceId, schema: 'read_model' },
  { title: 'acceptance_decision', tableName: 'acceptance_decision', sourceId: context.operatorSourceId, schema: 'operator' }
];
const resolved = expected.map((item) => ({ ...item, matches: tables.filter((table) => table && table.title === item.title && table.table_name === item.tableName && table.source_id === item.sourceId) }));
if (tables.length !== expected.length || resolved.some((item) => item.matches.length !== 1 || !item.matches[0].id)) throw new Error('acceptance_reflection_invalid');
const facts = resolved[0].matches[0];
const decisions = resolved[1].matches[0];
return [{ json: {
  ...context,
  factsTableId: facts.id,
  decisionTableId: decisions.id,
  reflectedSchemas: [...new Set(resolved.map((item) => item.schema))].sort(),
  reflectedTables: resolved.map((item) => ({ id: item.matches[0].id, title: item.title, tableName: item.tableName, sourceId: item.sourceId, schema: item.schema })).sort((left, right) => left.schema.localeCompare(right.schema)),
  cleanupOnly: context.operation === 'cleanup'
} }];

const direct = $json.rows !== undefined ? $json : null;
let context = direct;
if (!context) {
  try { context = $('Continue Cleanup').last().json; } catch { context = $('Initialize Cleanup').first().json; }
}
const raw = direct ? direct.rows : $json;
const rows = Array.isArray(raw) ? raw : (raw.list || []);
if (rows.length > 100 || rows.some((row) => row.run_id !== context.runId || (row.id ?? row.Id) === undefined)) throw new Error('cleanup_scope_invalid');
if (rows.length > 0 && Number(context.cleanupPageCount || 0) >= 10) throw new Error('cleanup_page_bound_exceeded');
return [{ json: {
  ...context,
  hasRows: rows.length > 0,
  cleanupPageCount: Number(context.cleanupPageCount || 0) + (rows.length > 0 ? 1 : 0),
  removedCount: Number(context.removedCount || 0) + rows.length,
  deleteRows: rows.map((row) => ({ id: row.id ?? row.Id }))
} }];

const context = $('Resolve Acceptance Tables').first().json;
const record = Array.isArray($json) ? $json[0] : $json;
const recordId = record?.id ?? record?.Id;
if (recordId === undefined || recordId === null) throw new Error('inserted_decision_id_missing');
return [{ json: { ...context, recordId } }];

const context = $('Normalize Inserted Decision').first().json;
const rows = Array.isArray($json) ? $json : ($json.list || []);
const matches = rows.filter((row) => row && row.run_id === context.runId && (row.id ?? row.Id) === context.recordId);
if (matches.length !== 1 || matches[0].decision !== 'pending') throw new Error('insert_probe_failed');
return [{ json: { ...context, protectedCreatedAt: matches[0].protected_created_at } }];

const context = $('Require Inserted Decision').first().json;
const rows = Array.isArray($json) ? $json : ($json.list || []);
const matches = rows.filter((row) => row && row.run_id === context.runId && (row.id ?? row.Id) === context.recordId);
if (matches.length !== 1 || matches[0].decision !== 'approved' || matches[0].protected_created_at !== context.protectedCreatedAt) throw new Error('update_probe_failed');
return [{ json: context }];

const context = $json.context || $('Require Updated Decision').first().json;
const body = $json.body || {};
if ($json.statusCode !== 400 || body.error !== 'ERR_DATABASE_OP_FAILED' || body.code !== '42501' || !/permission to access 'acceptance_decision'/i.test(String(body.message || ''))) throw new Error('protected_update_denial_invalid');
return [{ json: { ...context, protectedUpdateDenied: true, protectedUpdateStatus: 400, protectedUpdateEvidence: 'postgresql_42501' } }];

const context = $json.context || $('Prepare Reader Negative Probe').first().json;
const body = $json.body || {};
if ($json.statusCode === 403 && body.error === 'ERR_FORBIDDEN' && String(body.message || '') === "Forbidden - Source 'Read Model' is read-only") {
  return [{ json: { ...context, readerInsertDenied: true, readerInsertStatus: 403, readerInsertEvidence: 'source_read_only', unexpectedlyPermitted: false } }];
}
if ($json.statusCode >= 200 && $json.statusCode < 300) {
  return [{ json: { ...context, readerInsertDenied: false, unexpectedlyPermitted: true } }];
}
throw new Error('reader_insert_denial_invalid');

const context = $json.context || $('Prepare Cleanup Page').last().json;
const body = $json.body;
if ($json.statusCode !== 200 || !body || !Array.isArray(body.list) || !body.pageInfo || body.list.length !== 0) throw new Error('cleanup_absence_invalid');
return [{ json: { ok: true, operation: 'cleanup', runId: context.runId, domain: 'issue334_acceptance', removedCount: context.removedCount } }];

const context = $json.context || $('Cleanup Only').first().json;
const body = $json.body;
if ($json.statusCode !== 200 || !body || !Array.isArray(body.list) || !body.pageInfo || body.list.length > 1) throw new Error('reader_read_invalid');
return [{ json: { ...context, readerRead: true } }];

const context = $('Capture Protected Update Denial').first().json;
let hash = 2166136261;
for (const character of context.runId) { hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0; }
return [{ json: { ...context, readerProbeId: 8000000000 + hash, readerProbeFact: `forbidden:${context.runId}` } }];

const context = $('Evaluate Reader Insert Denial').first().json;
const rows = Array.isArray($json) ? $json : ($json.list || []);
if (rows.some((row) => row.run_id === context.runId)) throw new Error('probe_cleanup_failed');
return [{ json: {
  ok: true,
  operation: 'probe',
  runId: context.runId,
  domain: 'issue334_acceptance',
  inserted: true,
  read: true,
  readerRead: context.readerRead === true,
  decisionUpdated: true,
  removed: true,
  reflectedSchemas: context.reflectedSchemas,
  reflectedTables: context.reflectedTables,
  forbiddenOperations: {
    protectedUpdateDenied: context.protectedUpdateDenied,
    protectedUpdateStatus: context.protectedUpdateStatus,
    protectedUpdateEvidence: context.protectedUpdateEvidence,
    readerInsertDenied: context.readerInsertDenied,
    readerInsertStatus: context.readerInsertStatus,
    readerInsertEvidence: context.readerInsertEvidence
  }
} }];
